int Hash(string s, int groesse)
{
    int summe = 0;
    foreach (char c in s)
        summe += c;
    return summe % groesse;
}

Hash("x", 7)     // 1
Hash("y", 7)     // 2
Hash("i", 7)     // 0
Hash("anna", 7)  // 1
Hash("otto", 7)  // 6
Hash("ab", 7)    // 6
Hash("ba", 7)    // 6  <- Kollision!

