int Index(object key, int n) =>
    (key.GetHashCode() & 0x7FFFFFFF) % n;
Console.WriteLine(Index(17, 10));   // 7
Console.WriteLine(Index(27, 10));   // 7

class Punkt
{
    public int X { get; }
    public int Y { get; }
    public Punkt(int x, int y)
        { X = x; Y = y; }
    public override bool Equals(object o) =>
        o is Punkt p && p.X == X && p.Y == Y;
    public override int GetHashCode() =>
        HashCode.Combine(X, Y);
}
